INSERT INTO public."Block" VALUES (226, 57, '{"type": "richText", "content": "<h2 class=\"section-header\">The most overlooked units</h2>\n<p>Have you ever had a game where you had 10+ mythics on the board all at the same time, but still somehow lost? You get so many strong mythics out there, you feel like you should win easily but you don''t? This happens all the time, and it''s because people don''t know that a couple of the&nbsp;<strong>best units in the game aren''t mythics at all.</strong></p>\n<p>These following units aren''t mythic, but are <strong>nearly required in every run to win.</strong></p>"}', 45, NULL);
